//! The interface language: the one list of supported languages
//! ([`Language`]), the one place that decides which one a request gets
//! (`resolve_language`), and the one signal everything reads
//! ([`language_signal`]), provided once at the app root
//! ([`provide_language`]).
//!
//! Each crate keeps its own strings in its own typed catalogue
//! (`leptos_i18n`, generated by its `build.rs` from `locales/<code>.json`):
//! the library's strings stay in the library, an app's in the app. What
//! joins them is this module: every catalogue's `Locale` implements
//! `From<Language>` with an exhaustive `match`, so a new [`Language`]
//! variant does not build until every crate has its translations, and a
//! page never mixes languages — every catalogue reads the same signal.
//!
//! **Where the first value comes from.** On the server, from the request:
//! cookie `pc_lang`, else the `Accept-Language` header, else English
//! (`resolve_language`); the server's shell also writes it into
//! `<html lang>`. In the browser, hydration starts from that `<html lang>`
//! — the language the server rendered — and never re-resolves it from the
//! cookie or a default, so the hydrated page cannot flash another language.
//! A choice made later is written back to `pc_lang`
//! ([`persisted_with`](crate::persisted::persisted_with)), shared by every
//! `*.palicanon.app` service, and applies live, without a reload.
//!
//! A page with no server (`csr`, [`Store::Local`](crate::store::Store::Local)) has no `<html lang>` to
//! start from: the stored `pc_lang`, else the first supported entry of
//! `navigator.languages`, else English. That detection is read only, never
//! written: only a choice is stored.

use std::fmt;
use std::str::FromStr;

use leptos::prelude::*;

use crate::persisted;

/// The cookie name, without its `pc_` prefix.
const COOKIE: &str = "lang";

/// The languages of the interface.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum Language {
    /// English: the default, and the fallback when nothing else matches.
    #[default]
    En,
    /// French.
    Fr,
    /// Vietnamese.
    Vi,
}

impl Language {
    /// Every language, in the order a language menu lists them.
    pub const ALL: [Language; 3] = [Language::En, Language::Fr, Language::Vi];

    /// Its BCP 47 code: the `pc_lang` cookie value and `<html lang>`.
    #[must_use]
    pub fn code(self) -> &'static str {
        match self {
            Language::En => "en",
            Language::Fr => "fr",
            Language::Vi => "vi",
        }
    }

    /// Its name in itself ("Français", not "French"): how a language menu
    /// shows it, so a reader finds their own language whatever the page's.
    #[must_use]
    pub fn name(self) -> &'static str {
        match self {
            Language::En => "English",
            Language::Fr => "Français",
            Language::Vi => "Tiếng Việt",
        }
    }

    /// The language of a BCP 47 tag, by its primary subtag, ignoring case:
    /// `fr`, `fr-CA` and `FR` are all French. `None` for any other.
    #[must_use]
    pub fn from_tag(tag: &str) -> Option<Language> {
        let primary = tag.split(['-', '_']).next()?.trim();
        Language::ALL
            .into_iter()
            .find(|language| language.code().eq_ignore_ascii_case(primary))
    }
}

impl fmt::Display for Language {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.code())
    }
}

/// A language code did not match `"en"`, `"fr"` or `"vi"` exactly.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ParseLanguageError;

impl FromStr for Language {
    type Err = ParseLanguageError;

    /// Exactly a [`Language::code`]: what the `pc_lang` cookie holds.
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Language::ALL
            .into_iter()
            .find(|language| language.code() == s)
            .ok_or(ParseLanguageError)
    }
}

/// The best supported language of an `Accept-Language` header: its tags
/// by decreasing `q` (`Q` too: the name ignores case; 1 when absent;
/// `q=0` means "not this one"), the first one that is a [`Language`]
/// wins. `None` when none is.
#[cfg(any(feature = "ssr", test))]
fn from_accept_language(header: &str) -> Option<Language> {
    let mut ranked: Vec<(f32, Language)> = header
        .split(',')
        .filter_map(|entry| {
            let mut fields = entry.split(';');
            let language = Language::from_tag(fields.next()?)?;
            let q = fields
                .find_map(|field| {
                    let (name, value) = field.trim().split_once('=')?;
                    name.eq_ignore_ascii_case("q").then_some(value)
                })
                .map_or(1.0, |q| q.trim().parse().unwrap_or(1.0));
            (q > 0.0).then_some((q, language))
        })
        .collect();
    // Stable: equal weights keep the header's own order.
    ranked.sort_by(|a, b| b.0.total_cmp(&a.0));
    ranked.first().map(|&(_, language)| language)
}

/// The decision behind [`resolve_language`], on the raw header values:
/// `pc_lang` when it holds a known language, else `Accept-Language`'s best
/// supported one, else English.
#[cfg(any(feature = "ssr", test))]
fn resolve(cookies: Option<&str>, accept_language: Option<&str>) -> Language {
    let key = format!("{}{COOKIE}", persisted::PREFIX);
    cookies
        .and_then(|cookies| persisted::cookie_value(cookies, &key))
        .and_then(|raw| raw.parse().ok())
        .or_else(|| accept_language.and_then(from_accept_language))
        .unwrap_or_default()
}

/// The language a request is rendered in — the one owner of that
/// decision: cookie `pc_lang` when it holds a known language, else the
/// best supported language of the `Accept-Language` header, else English.
#[cfg(feature = "ssr")]
#[must_use]
pub fn resolve_language(parts: &http::request::Parts) -> Language {
    let header = |name| {
        parts
            .headers
            .get(name)
            .and_then(|value: &http::HeaderValue| value.to_str().ok())
    };
    resolve(
        header(http::header::COOKIE),
        header(http::header::ACCEPT_LANGUAGE),
    )
}

/// The language the server rendered, as hydration reads it back from
/// `<html lang>`: English when the attribute is missing or unknown.
#[cfg(any(feature = "browser", test))]
fn from_html_lang(lang: Option<&str>) -> Language {
    lang.and_then(Language::from_tag).unwrap_or_default()
}

/// The language of a page that keeps its preferences in `localStorage`:
/// the stored `pc_lang` when it holds a known language, else the first of
/// the browser's `navigator.languages` that is supported, else English. It
/// only reads: a detected locale is never written back, so it stays
/// distinguishable from a choice (as `Accept-Language` is on the server).
#[cfg(any(feature = "browser", test))]
fn pick_language(stored: Option<&str>, navigator: &[String]) -> Language {
    persisted_language(stored)
        .or_else(|| navigator.iter().find_map(|tag| Language::from_tag(tag)))
        .unwrap_or_default()
}

/// `pc_lang`'s value as a language: exactly a [`Language::code`].
#[cfg(any(feature = "browser", test))]
fn persisted_language(stored: Option<&str>) -> Option<Language> {
    crate::store::parse_stored(stored)
}

/// `navigator.languages`, most preferred first (empty without a window).
#[cfg(feature = "browser")]
fn navigator_languages() -> Vec<String> {
    web_sys::window()
        .map(|window| {
            let languages = window.navigator().languages();
            languages.iter().filter_map(|tag| tag.as_string()).collect()
        })
        .unwrap_or_default()
}

/// The language under [`Store::Local`](crate::store::Store::Local): [`pick_language`] over the real
/// `localStorage` and `navigator.languages`. Also what
/// `csr::mount` puts into `<html lang>` before the first render.
#[cfg(feature = "browser")]
pub(crate) fn local_language() -> Language {
    let key = format!("{}{COOKIE}", persisted::PREFIX);
    pick_language(
        crate::store::Store::Local.read(&key).as_deref(),
        &navigator_languages(),
    )
}

/// The first value of [`language_signal`]: the request's
/// (`resolve_language`) on the server; in the browser, [`local_language`]
/// under [`Store::Local`](crate::store::Store::Local), else `<html lang>` (the language the server
/// rendered); English when none exists (a plain test).
fn initial_language() -> Language {
    #[cfg(feature = "ssr")]
    {
        use_context::<http::request::Parts>()
            .map(|parts| resolve_language(&parts))
            .unwrap_or_default()
    }
    #[cfg(all(feature = "browser", not(feature = "ssr")))]
    {
        if crate::store::Store::current() == crate::store::Store::Local {
            return local_language();
        }
        let lang = document()
            .document_element()
            .and_then(|root| root.get_attribute("lang"));
        from_html_lang(lang.as_deref())
    }
    #[cfg(not(any(feature = "ssr", feature = "browser")))]
    {
        Language::default()
    }
}

/// Provides the page's one language signal, at the app root: called once
/// where the page starts — the server's document shell (which writes
/// `<html lang>` from it), and the component the browser hydrates (the
/// server's shell is not hydrated, so that component starts the browser's
/// owner tree). It starts from the request on the server and from
/// `<html lang>` in the browser.
///
/// Idempotent: below an owner that already provided it, it returns that
/// signal — the app the server's shell renders shares the shell's.
/// [`crate::shell::AppShell`] calls it too, so an app that forgets the
/// root call still has one signal under its shell.
pub fn provide_language() -> RwSignal<Language> {
    if let Some(signal) = use_context::<RwSignal<Language>>() {
        return signal;
    }
    let signal = persisted::persisted_with(COOKIE, initial_language());
    provide_context(signal);
    signal
}

/// The interface language: the signal [`provide_language`] put at the app
/// root, read through Leptos context — the library's components and the
/// app's own catalogue all read this one signal. Setting it switches every
/// string live and stores the choice in `pc_lang`.
///
/// Outside an app root (a component rendered alone, a test), nothing
/// provided it: the first call creates one, as [`provide_language`] would,
/// in the caller's own owner — shared below it, not with its siblings.
#[must_use]
pub fn language_signal() -> RwSignal<Language> {
    use_context::<RwSignal<Language>>().unwrap_or_else(provide_language)
}

/// The `lang` attribute `<html>` carries for the first render of a page,
/// as [`crate::theme::theme_attribute`] gives its `data-theme`: the code
/// of the request's language. Called by the server's document shell, it
/// also provides the page's signal there ([`provide_language`]), so the
/// app it renders shares it — and the browser's hydration reads this very
/// attribute back, so the hydrated page starts in the language the server
/// rendered:
///
/// ```ignore
/// view! { <html lang=language_attribute() data-theme=theme_attribute()>/* … */</html> }
/// ```
///
/// The browser keeps it in step with later switches
/// ([`crate::shell::AppShell`]).
#[must_use]
pub fn language_attribute() -> &'static str {
    provide_language().get_untracked().code()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_language_has_its_code_and_its_own_name() {
        let table: Vec<_> = Language::ALL
            .into_iter()
            .map(|l| (l.code(), l.name()))
            .collect();
        assert_eq!(
            table,
            [("en", "English"), ("fr", "Français"), ("vi", "Tiếng Việt")]
        );
        assert_eq!(Language::default(), Language::En);
    }

    #[test]
    fn codes_round_trip_and_nothing_else_parses() {
        for language in Language::ALL {
            assert_eq!(language.to_string().parse(), Ok(language));
        }
        for garbled in ["", "de", "FR", "fr-CA", " en", "english"] {
            assert!(garbled.parse::<Language>().is_err(), "{garbled:?}");
        }
    }

    #[test]
    fn a_tag_is_matched_by_its_primary_subtag_ignoring_case() {
        assert_eq!(Language::from_tag("fr"), Some(Language::Fr));
        assert_eq!(Language::from_tag("fr-CA"), Some(Language::Fr));
        assert_eq!(Language::from_tag("FR"), Some(Language::Fr));
        assert_eq!(Language::from_tag("vi-VN"), Some(Language::Vi));
        assert_eq!(Language::from_tag("en_GB"), Some(Language::En));
        assert_eq!(Language::from_tag("de-DE"), None);
        assert_eq!(Language::from_tag("frisian"), None, "a prefix is no match");
        assert_eq!(Language::from_tag(""), None);
    }

    #[test]
    fn accept_language_picks_the_highest_q_that_is_supported() {
        assert_eq!(from_accept_language("fr"), Some(Language::Fr));
        assert_eq!(
            from_accept_language("de-DE,de;q=0.9,vi;q=0.8,fr;q=0.7"),
            Some(Language::Vi),
            "German first, unsupported: the next one by q"
        );
        assert_eq!(
            from_accept_language("fr;q=0.5, vi;q=0.9"),
            Some(Language::Vi),
            "by q, not by position"
        );
        assert_eq!(
            from_accept_language("vi;q=0, fr;q=0.1"),
            Some(Language::Fr),
            "q=0 refuses a language"
        );
        assert_eq!(from_accept_language("en-US,en;q=0.9"), Some(Language::En));
        assert_eq!(from_accept_language("de, *;q=0.5"), None, "* is no choice");
        assert_eq!(from_accept_language(""), None);
        assert_eq!(
            from_accept_language("fr;q=abc"),
            Some(Language::Fr),
            "a garbled q counts as 1"
        );
    }

    /// RFC 9110: the `q` parameter's name is case-insensitive (T13).
    #[test]
    fn an_upper_case_q_is_a_weight_too() {
        assert_eq!(
            from_accept_language("fr;Q=0.5, vi;q=0.9"),
            Some(Language::Vi)
        );
        assert_eq!(from_accept_language("vi;Q=0, fr;q=0.1"), Some(Language::Fr));
    }

    #[test]
    fn the_cookie_beats_accept_language() {
        assert_eq!(
            resolve(Some("pc_theme=dark; pc_lang=vi"), Some("fr")),
            Language::Vi
        );
    }

    /// A host-only `pc_lang` and a `Domain=palicanon.app` one can both be
    /// sent; the first in the header is the one taken (T12).
    #[test]
    fn of_two_pc_lang_cookies_the_first_sent_wins() {
        assert_eq!(resolve(Some("pc_lang=fr; pc_lang=vi"), None), Language::Fr);
        assert_eq!(
            resolve(Some("pc_rail=true; pc_lang=vi; pc_lang=fr"), Some("en")),
            Language::Vi
        );
    }

    #[test]
    fn a_garbled_cookie_falls_back_to_accept_language() {
        assert_eq!(resolve(Some("pc_lang=klingon"), Some("fr")), Language::Fr);
        assert_eq!(resolve(Some("pc_lang="), Some("vi-VN")), Language::Vi);
    }

    #[test]
    fn no_cookie_takes_accept_language() {
        assert_eq!(resolve(None, Some("vi-VN,vi;q=0.9")), Language::Vi);
        assert_eq!(resolve(Some("pc_rail=true"), Some("fr-FR")), Language::Fr);
    }

    #[test]
    fn nothing_usable_is_english() {
        assert_eq!(resolve(None, None), Language::En);
        assert_eq!(resolve(None, Some("de-DE,ja;q=0.5")), Language::En);
        assert_eq!(resolve(Some("pc_lang=xx"), Some("de")), Language::En);
    }

    #[test]
    fn the_stored_language_beats_the_browsers() {
        assert_eq!(pick_language(Some("vi"), &["fr".into()]), Language::Vi);
    }

    #[test]
    fn without_a_stored_language_the_first_supported_browser_one_wins() {
        let navigator = ["de-DE", "FR-ca", "vi"].map(String::from);
        assert_eq!(pick_language(None, &navigator), Language::Fr);
        assert_eq!(pick_language(None, &["en-US".into()]), Language::En);
    }

    #[test]
    fn a_garbled_stored_language_falls_to_the_browsers_then_english() {
        assert_eq!(
            pick_language(Some("klingon"), &["vi-VN".into()]),
            Language::Vi
        );
        assert_eq!(
            pick_language(Some("fr-CA"), &[]),
            Language::En,
            "exact codes"
        );
        assert_eq!(
            pick_language(None, &["de".into(), "ja".into()]),
            Language::En
        );
        assert_eq!(pick_language(None, &[]), Language::En);
    }

    #[test]
    fn an_empty_or_unsupported_navigator_list_is_english() {
        assert_eq!(pick_language(None, &[]), Language::En, "empty");
        let unsupported = ["de-DE", "ja", "zh-Hant", ""].map(String::from);
        assert_eq!(
            pick_language(None, &unsupported),
            Language::En,
            "unsupported"
        );
        assert_eq!(
            pick_language(Some(""), &unsupported),
            Language::En,
            "empty store"
        );
    }

    #[test]
    fn hydration_reads_html_lang_and_defaults_to_english() {
        assert_eq!(from_html_lang(Some("vi")), Language::Vi);
        assert_eq!(from_html_lang(Some("fr")), Language::Fr);
        assert_eq!(from_html_lang(None), Language::En);
        assert_eq!(from_html_lang(Some("de")), Language::En);
    }

    #[test]
    fn language_signal_is_the_same_instance_across_calls_in_one_owner() {
        Owner::new().with(|| {
            language_signal().set(Language::Fr);
            assert_eq!(language_signal().get_untracked(), Language::Fr);
        });
    }

    #[test]
    fn provide_language_below_a_provided_one_reuses_it() {
        Owner::new().with(|| {
            let page = provide_language();
            let again = Owner::current().unwrap().child().with(provide_language);
            assert_eq!(
                again, page,
                "the server shell's, reused by the app inside it"
            );
        });
    }

    #[test]
    fn without_a_request_the_language_is_english() {
        Owner::new().with(|| assert_eq!(language_signal().get_untracked(), Language::En));
    }

    #[cfg(feature = "ssr")]
    fn parts(cookie: Option<&str>, accept: Option<&str>) -> http::request::Parts {
        let mut request = http::Request::builder();
        if let Some(cookie) = cookie {
            request = request.header(http::header::COOKIE, cookie);
        }
        if let Some(accept) = accept {
            request = request.header(http::header::ACCEPT_LANGUAGE, accept);
        }
        request.body(()).unwrap().into_parts().0
    }

    #[cfg(feature = "ssr")]
    #[test]
    fn the_server_resolves_from_the_request_headers() {
        assert_eq!(
            resolve_language(&parts(Some("pc_lang=vi"), Some("fr"))),
            Language::Vi
        );
        assert_eq!(resolve_language(&parts(None, Some("fr-CA"))), Language::Fr);
        assert_eq!(resolve_language(&parts(None, None)), Language::En);
    }

    /// T1, as far as a test without a document goes: hydration's start is
    /// `<html lang>` (vi) through `persisted_with`, which never reads the
    /// cookie (fr) — so the page hydrates in the language it was rendered
    /// in. The `document()` read itself is browser-only (task 024).
    #[cfg(feature = "ssr")]
    #[test]
    fn hydration_starts_from_html_lang_not_from_the_cookie() {
        Owner::new().with(|| {
            provide_context(parts(Some("pc_lang=fr"), None));
            let hydrated = persisted::persisted_with(COOKIE, from_html_lang(Some("vi")));
            assert_eq!(hydrated.get_untracked(), Language::Vi);
        });
    }

    #[cfg(feature = "ssr")]
    #[test]
    fn on_the_server_language_signal_starts_from_the_request() {
        Owner::new().with(|| {
            provide_context(parts(Some("pc_lang=fr"), Some("vi")));
            assert_eq!(language_signal().get_untracked(), Language::Fr);
        });
    }

    #[cfg(feature = "ssr")]
    #[test]
    fn the_html_lang_attribute_is_the_requests_language_and_the_pages_signal() {
        Owner::new().with(|| {
            provide_context(parts(Some("pc_lang=vi"), Some("fr")));
            assert_eq!(language_attribute(), "vi");
            let app = Owner::current().unwrap().child().with(language_signal);
            assert_eq!(app.get_untracked(), Language::Vi);
            assert_eq!(app, provide_language(), "the app below shares it");
        });
    }

    #[test]
    fn without_a_request_html_lang_is_english() {
        assert_eq!(Owner::new().with(language_attribute), "en");
    }
}
